pub fn [median](_values: &[i64]) -> [Option]<[f64]> {
    let mut sorted: [i64] = _values.iter().copied().collect();
    sorted.sort();
    let n: usize = sorted.len();
    if n == 0 {
        return None;
    }
    let mut result = [Option::None; n];
    let mut start = 0;
    let mut end = n / 2;
    for (i, &val) in sorted.iter().enumerate() {
        if i < end {
            result[i] = Some((val as f64).max(0.0).min(f64::MAX));
        } else if i == end {
            result[i] = Some((val as f64).min(f64::MAX));
        } else {
            result[i] = None;
        }
    }
    result
}

